/* ============================================================================
   Titan Fitness - demo seed data
   - Run against the TitanFitnessDb database (after the migrations were applied).
   - WARNING: this script DELETES all existing rows first, then re-creates the demo data.
   - All dates are relative to the moment you run it, so "today" always has classes,
     check-ins and an in-progress session.  Re-run it any time to refresh the data.
   ============================================================================ */
USE TitanFitnessDb;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @now      DATETIME2(0) = SYSDATETIME();
DECLARE @today    DATE         = CAST(@now AS DATE);
DECLARE @todayDT  DATETIME2(0) = CAST(@today AS DATETIME2(0));
DECLARE @minToday INT          = DATEDIFF(MINUTE, @todayDT, @now);
DECLARE @nowMin   DATETIME2(0) = DATEADD(MINUTE, DATEDIFF(MINUTE, @todayDT, @now), @todayDT);
DECLARE @round    DATETIME2(0) = DATEADD(MINUTE, -(DATEPART(MINUTE, @nowMin) % 5), @nowMin);
DECLARE @liveStart DATETIME2(0) = DATEADD(MINUTE, -20, @round);   -- session already in progress
DECLARE @upcStart  DATETIME2(0) = DATEADD(MINUTE, 45, @round);    -- session starting soon

-- ---- wipe (children first) ----
DELETE FROM Bookings;
DELETE FROM CheckIns;
DELETE FROM GuestPasses;
DELETE FROM Freezes;
DELETE FROM Memberships;
DELETE FROM ClassSessions;
DELETE FROM PlanBranches;
DELETE FROM Plans;
DELETE FROM Trainers;
DELETE FROM Members;
DELETE FROM Studios;
DELETE FROM Branches;

DBCC CHECKIDENT ('Bookings', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('CheckIns', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('GuestPasses', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Freezes', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Memberships', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('ClassSessions', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Plans', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Trainers', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Members', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Studios', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('Branches', RESEED, 0) WITH NO_INFOMSGS;

