-- Extend each membership end date by its frozen days (as the application does when a freeze is added)
UPDATE ms SET EndDate = DATEADD(DAY, f.TotalDays, ms.EndDate)
FROM Memberships ms
JOIN (SELECT MembershipId, SUM(DATEDIFF(DAY, StartDate, EndDate)) AS TotalDays FROM Freezes GROUP BY MembershipId) f
  ON f.MembershipId = ms.MembershipId;

