-- Check-outs: admitted check-ins older than ~50-90 minutes are checked out; the most recent ones remain "on the floor"
UPDATE CheckIns
SET CheckOutDateTime = DATEADD(MINUTE, 50 + (CheckInId % 40), CheckInDateTime)
WHERE Result = 1 AND DATEADD(MINUTE, 50 + (CheckInId % 40), CheckInDateTime) < @now;

-- Past sessions: booked members attended (about 1 in 11 was a no-show); waitlisted members were released
UPDATE bk SET Status = CASE WHEN bk.BookingId % 11 = 0 THEN 4 ELSE 3 END
FROM Bookings bk
JOIN ClassSessions cs ON cs.SessionId = bk.SessionId
WHERE bk.Status = 1 AND cs.Status <> 4
  AND DATEADD(MINUTE, cs.DurationInMinutes, DATEADD(SECOND, DATEDIFF(SECOND, CAST('00:00:00' AS TIME), cs.StartTime), CAST(cs.SessionDate AS DATETIME2(0)))) < @now;

UPDATE bk SET Status = 5, WaitlistPosition = NULL
FROM Bookings bk
JOIN ClassSessions cs ON cs.SessionId = bk.SessionId
WHERE bk.Status = 2 AND cs.Status <> 4
  AND DATEADD(MINUTE, cs.DurationInMinutes, DATEADD(SECOND, DATEDIFF(SECOND, CAST('00:00:00' AS TIME), cs.StartTime), CAST(cs.SessionDate AS DATETIME2(0)))) < @now;

COMMIT TRANSACTION;

